import js from '@eslint/js'
import globals from 'globals'
import tseslint from 'typescript-eslint'
import sortiva from 'eslint-plugin-sortiva'

export default tseslint.config(
  {
    ignores: [
      '**/node_modules/**',
      '**/dist/**',
      '**/.next/**',
      '**/coverage/**',
      'tmp/**',
      'docs/**',
      // Generated by `next build`; its triple-slash references are Next's, not ours.
      '**/next-env.d.ts',
    ],
  },

  js.configs.recommended,
  ...tseslint.configs.recommended,

  {
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: { ...globals.node },
    },
    plugins: { sortiva },
    rules: {
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_' },
      ],
      '@typescript-eslint/no-explicit-any': 'warn',

      // Invariant 25 — one instrumented wrapper per vendor SDK.
      'sortiva/no-direct-provider-sdk': 'error',

      // Invariant 25, for the vendor with no SDK to ban: DataForSEO is a plain
      // HTTPS endpoint, so the host string itself is what has to be fenced in.
      'sortiva/no-direct-vendor-http': 'error',

      // Invariant 9 — every threshold number lives in packages/rules.
      'sortiva/no-threshold-literals': 'error',

      // No code outside packages/db
      // may import a raw table or the raw database handle, so no query can
      // reach a table without naming the account whose data it touches.
      // Audit T0.3 [major]; remediation D5 (stopgap half).
      'sortiva/no-raw-db-access': 'error',

      // Invariant 24 — the sentences the product may not reword have one copy,
      // in the string catalogue, and are looked up by key.
      // `sortiva/no-literal-jsx-text` below keeps hand-written copy off
      // screens, but it reads JSX and nothing else; this one applies
      // everywhere, because the second copy of the pause line was found in a
      // route handler answering a request, where no JSX rule ever looks.
      'sortiva/no-canonical-copy-outside-catalogue': 'error',
    },
  },

  // The two places a canonical sentence is deliberately written out.
  //
  // `packages/core` may not import `packages/ui`, so the billing and
  // account-deletion promises that core itself has to keep are declared there
  // as constants and mirrored into the catalogue. The mirroring is not
  // unguarded: `packages/ui/src/strings/strings.test.ts` imports these very
  // constants and fails if they and the catalogue disagree, which is the
  // protection this rule exists to give. Journalled when it was done — see
  // DECISIONS 2026-08-31 T1.2.
  //
  // Do not add to this list. A new sentence belongs in the catalogue, looked up
  // by key; these two files are a bounded and tested exception, not a pattern.
  {
    files: ['packages/core/src/billing/copy.ts', 'packages/core/src/lifecycle/copy.ts'],
    rules: { 'sortiva/no-canonical-copy-outside-catalogue': 'off' },
  },

  // A test that holds a canonical sentence has to quote it — quoting it is what
  // makes it a snapshot rather than a restatement of whatever the code happens
  // to say today. The same goes for the browser tests that read the sentence
  // off a rendered page.
  {
    files: [
      '**/*.test.{ts,tsx}',
      '**/*.spec.{ts,tsx}',
      '**/fixtures/**',
      '**/__fixtures__/**',
      'apps/web/e2e/**',
    ],
    rules: { 'sortiva/no-canonical-copy-outside-catalogue': 'off' },
  },

  // The planted violation that proves this rule fires has to contain the
  // sentence the rule bans, the same way the vendor-host proof below contains
  // the host it bans.
  {
    files: ['scripts/lint-proofs/**'],
    rules: { 'sortiva/no-canonical-copy-outside-catalogue': 'off' },
  },

  // The rule that bans a vendor host has to name that host, and the test that
  // proves the rule works has to plant it. Those two files are the definition
  // and the proof, not a call site.
  {
    files: [
      'tools/eslint-plugin-sortiva/rules/no-direct-vendor-http.js',
      'scripts/prove-lint.mjs',
      // The planted violations themselves. Each case file exists to contain the
      // thing the rule bans; that is the whole point of it.
      'scripts/lint-proofs/**',
    ],
    rules: { 'sortiva/no-direct-vendor-http': 'off' },
  },

  // packages/rules is the one place threshold numbers are allowed to be compared.
  {
    files: ['packages/rules/**/*.{ts,tsx,js,mjs}'],
    rules: { 'sortiva/no-threshold-literals': 'off' },
  },

  // The two packages that read a file off disk to do their job — the thresholds
  // and the prompts. Both are reached from the web server's start-up hook, and
  // both used to work out where their file was while the module was loading. A
  // module address is not a path on disk in the production build, so that threw
  // on import, and a start-up hook that throws makes Next answer every request
  // with a 500 — which is what the product did, for days, with a green build and
  // a green test suite. The rule holds the repair in place: locate the file when
  // something asks for it, not when the module loads.
  //
  // Scoped to these two rather than the whole repository because these are where
  // the file reads are; a third package that starts reading a file off disk
  // belongs on this list on the day it does.
  {
    files: ['packages/rules/**/*.{ts,tsx,js,mjs}', 'packages/llm/**/*.{ts,tsx,js,mjs}'],
    rules: { 'sortiva/no-module-load-path-resolution': 'error' },
  },

  // A test is never bundled and never imported by the running server, and
  // finding a fixture relative to itself is a reasonable thing for one to do.
  {
    files: ['**/*.test.{ts,tsx}', '**/*.spec.{ts,tsx}'],
    rules: { 'sortiva/no-module-load-path-resolution': 'off' },
  },

  // Tests and fixtures assert against concrete numbers by definition; the rule
  // exists to stop *production* code carrying thresholds, not to stop tests
  // proving that packages/rules serves the right ones.
  {
    files: ['**/*.test.{ts,tsx}', '**/*.spec.{ts,tsx}', '**/fixtures/**', '**/__fixtures__/**'],
    rules: { 'sortiva/no-threshold-literals': 'off' },
  },

  // The bounded D5 exemption. `job_steps`, `ingestion_jobs`, `job_dlq` and
  // `idempotency_ledger` have no scoped repositories to call: `job_steps` has no
  // account_id column of its own (it hangs off ingestion_jobs), the ledger
  // deliberately has none at all so an account cascade cannot erase the record
  // that paid work was done, and supplying the helpers means editing packages/db, which
  // neither R1 nor R3 owns. These three files are the whole exemption; it is
  // named function-by-function in DECISIONS 2026-08-31 R1 and 2026-08-31 R3, and
  // ends when the durable D5 card lands.
  {
    files: [
      'packages/jobs/src/runtime/steps.ts',
      'packages/jobs/src/runtime/dlq.ts',
      'packages/jobs/src/runtime/ledger.ts',
    ],
    rules: { 'sortiva/no-raw-db-access': 'off' },
  },

  // Lane A's database code, which is a repository layer living in the wrong
  // directory. Every one of these files does name the account it acts for —
  // they take an AccountScope, filter on accountId, or are legitimately
  // system-scoped (the preview cache precedes any account, and the domain claim
  // must look across accounts, since asking "does anyone hold this?" is the
  // whole point of a claim). They sit in apps/web only because packages/db was
  // held by another session throughout wave 1, which each card journalled at the
  // time rather than working around silently.
  //
  // This is a location problem, not a scoping hole, and it is the durable half
  // of remediation D5. The exemption ends when that card moves these into
  // packages/db as scoped repositories. Do not add to this list: a new file that
  // needs it belongs in packages/db in the first place.
  {
    files: [
      'apps/web/app/api/account/_lib/load.ts',
      'apps/web/app/api/auth/_lib/provisioning.ts',
      'apps/web/app/api/billing/_lib/handlers.ts',
      'apps/web/app/api/billing/_lib/store.ts',
      'apps/web/app/api/domain/_lib/store.ts',
      'apps/web/app/api/preview/_lib/config.ts',
      'apps/web/app/api/preview/_lib/store.ts',
    ],
    rules: { 'sortiva/no-raw-db-access': 'off' },
  },

  // A composition root, not a query. This file never reads a table: it takes the
  // shared connection pool and hands it to the billing store, which is what makes
  // the per-account lock engage in production — before that, the lock ran only in
  // tests, the one place it was not needed. Naming concrete infrastructure is what
  // a composition root is for; the rule cannot tell "supplies a pool" from "queries
  // with one", so the distinction is recorded here instead.
  //
  // The durable version moves this construction into `apps/web/instrumentation.ts`,
  // the process's actual composition root, and passes the pool down. That is a
  // refactor, not a fix, and it belongs with the D5 card.
  {
    files: [
      'apps/web/app/api/webhooks/stripe/_lib/receiver.ts',
      // The process's actual composition root, which the note above names as
      // where this construction eventually belongs. It reads no table: it hands
      // the database factory to the spend-cap sweep's task registration, the
      // way it already hands the analytics client to the worker. A background
      // job cannot be given its database by a request, so somebody at the top
      // has to name it.
      'apps/web/instrumentation.ts',
      // Same shape again: the file that decides which Shopify, which page
      // fetcher, which database and which token cipher the store-connection
      // routes and the onboarding steps run against. It runs no query — every
      // query it enables goes through a repository that takes an account scope,
      // in `_lib/bindings.ts`, which takes its handles as arguments and is not
      // exempt. A route handler and a queue task are both called by their
      // framework, so neither has a caller of ours to be passed these by.
      'apps/web/app/api/shopify/_lib/config.ts',
      // T4.2's own two composition roots, on the identical shape: each hands
      // a raw `db()` handle to a constructor (`AnthropicLlmClient`,
      // `DataForSeoProvider`, `DbExistingTargetCheck`, or straight through as
      // `CalendarDeps.db`/`AddTopicDeps.db`) that a repository call later
      // scopes with an `AccountScope`. Neither file runs a query itself.
      'apps/web/app/api/calendar/_lib/config.ts',
      'apps/web/app/api/calendar/topics/_lib/config.ts',
      // T3.7's own composition root, identical shape: hands a raw `db()`
      // handle straight through as `OpportunitiesDeps.db`/`ScanStatusDeps.db`.
      // No query runs here — every one goes through a repository call scoped
      // with an `AccountScope` later.
      'apps/web/app/api/opportunities/_lib/config.ts',
      // T4.5's, identical again: hands a raw `db()` handle through as
      // `ReviewDeps.db` for the approve and discard routes. Every query it
      // enables runs in `packages/jobs/src/generation/review-article.ts`
      // behind an `AccountScope`; no query runs here.
      'apps/web/app/api/articles/_lib/config.ts',
      // T6.2's, the same shape once more: hands a raw `db()` handle through as
      // `RecommendationsDeps.db`, alongside the download's labels read from the
      // string catalogue. Every query it enables goes through
      // `packages/db/src/repositories/optimize.ts` behind an `AccountScope`.
      'apps/web/app/api/recommendations/_lib/config.ts',
      // T5.2's, the same shape again: decides which Shopify write client, which
      // token cipher and which database the auto-publish grant, blog picker and
      // delivery-mode routes run against, and hands the raw `db()` handle
      // through as `PublishGrantDeps.db`. No query runs here — every one goes
      // through `packages/db/src/repositories/publishing.ts` behind an
      // `AccountScope`.
      'apps/web/app/api/publish/_lib/config.ts',
    ],
    rules: { 'sortiva/no-raw-db-access': 'off' },
  },

  // Integration tests set up and inspect rows directly; the rule exists to stop
  // *production* code reaching a table without an account, not to stop a test
  // asserting on what the repositories wrote.
  {
    files: [
      '**/*.test.{ts,tsx}',
      '**/*.spec.{ts,tsx}',
      '**/testing.ts',
      '**/fixtures/**',
      // The chaos scenarios are test code that has to set up and
      // inspect rows a repository does not expose.
      'packages/jobs/src/chaos/**',
    ],
    rules: { 'sortiva/no-raw-db-access': 'off' },
  },

  // CLAUDE.md: route handlers parse -> call core -> serialise.
  {
    files: ['apps/web/app/api/**/route.{ts,tsx}'],
    rules: { 'sortiva/route-handler-imports': 'error' },
  },

  {
    files: ['**/*.{jsx,tsx}'],
    languageOptions: { globals: { ...globals.browser } },
    rules: {
      // Every sentence the merchant reads lives in packages/ui/strings, so it
      // can be reviewed, translated, and — for the ones the product may not
      // reword — held exact by a snapshot.
      'sortiva/no-literal-jsx-text': 'error',
    },
  },

  // A gallery that exists to render one component in each of its states. The
  // labels naming those states are scaffolding for whoever is looking at the
  // page, not product copy — externalising them would put words in the
  // catalogue that no merchant will ever see.
  {
    files: ['**/*.preview.tsx'],
    rules: { 'sortiva/no-literal-jsx-text': 'off' },
  },

  {
    files: ['scripts/**/*.mjs', 'tools/**/*.js', '*.config.{js,mjs,ts}'],
    rules: { '@typescript-eslint/no-unused-vars': 'off' },
  },
)
